svg.script:
console.log('[SVG Site Popup] Script executing');
(function () {
  function init() {
    var doc = document;
    var svg = doc.getElementById('svg1') || doc.querySelector('svg');
    if (!svg) {
      console.log('[SVG Site Popup] FAIL: SVG not found');
      return;
    }

    var tip = doc.getElementById('site-tooltip');
    var tooltipRect = doc.getElementById('tooltip-bg');
    var tooltipShadow = doc.getElementById('tooltip-shadow');
    var tooltipAccent = doc.getElementById('tooltip-accent');
    var siteNameText = doc.getElementById('tooltip-site-name');
    var telemetryText = doc.getElementById('tooltip-telemetry');
    var assetText = doc.getElementById('tooltip-asset');

    // Separate hover label: site name only. This remains independent of the
    // existing click popup and filter behaviour.
    var hoverTip = doc.getElementById('hover-tooltip');
    var hoverTooltipRect = doc.getElementById('hover-tooltip-bg');
    var hoverSiteNameText = doc.getElementById('hover-tooltip-site-name');
    var hoverReady = !!(hoverTip && hoverTooltipRect && hoverSiteNameText);
    if (hoverReady) hoverTip.style.pointerEvents = 'none';

    // The status legend is display-only and is excluded from all site actions.
    var statusLegend = doc.getElementById('status-legend');


    if (!tip || !tooltipRect || !siteNameText || !telemetryText || !assetText) {
      console.log('[SVG Site Popup] FAIL: tooltip elements not found');
      return;
    }

    var sites = doc.querySelectorAll('.site-marker, .Site, [id^="site-"]');
    if (!sites.length) {
      console.log('[SVG Site Popup] FAIL: no site/point elements found');
      return;
    }

    console.log('[SVG Site Popup] init OK, ' + sites.length + ' clickable points');

    function getSvgPoint(evt) {
      var pt = svg.createSVGPoint();
      pt.x = evt.clientX;
      pt.y = evt.clientY;
      var ctm = svg.getScreenCTM();
      return ctm ? pt.matrixTransform(ctm.inverse()) : pt;
    }

    function getViewBoxSize() {
      var vb = svg.viewBox && svg.viewBox.baseVal;
      if (vb && vb.width && vb.height) return vb;
      return {
        x: 0,
        y: 0,
        width: parseFloat(svg.getAttribute('width')) || 66,
        height: parseFloat(svg.getAttribute('height')) || 55
      };
    }

    function setTooltipSize(siteName, telemetryId, assetId) {
      var longest = Math.max((siteName || '').length, ('Telemetry ID: ' + (telemetryId || '')).length, ('Asset ID: ' + (assetId || '')).length);
      var width = Math.max(14.3, Math.min(21.4, 1.78 + longest * 0.54));
      var height = 4.55;

      tooltipRect.setAttribute('width', width);
      tooltipRect.setAttribute('height', height);
      if (tooltipShadow) {
        tooltipShadow.setAttribute('width', width);
        tooltipShadow.setAttribute('height', height);
      }
      if (tooltipAccent) {
        tooltipAccent.setAttribute('height', height);
      }
    }

    function positionTooltip(evt) {
      var pt = getSvgPoint(evt);
      var rectW = parseFloat(tooltipRect.getAttribute('width')) || 13;
      var rectH = parseFloat(tooltipRect.getAttribute('height')) || 2.75;
      var vb = getViewBoxSize();
      var offset = 0.38;

      var x = pt.x + offset;
      var y = pt.y - rectH - offset;

      if (x + rectW > vb.x + vb.width) x = pt.x - rectW - offset;
      if (y < vb.y) y = pt.y + offset;
      if (x < vb.x) x = vb.x + 0.15;
      if (y < vb.y) y = vb.y + 0.15;
      if (x + rectW > vb.x + vb.width) x = vb.x + vb.width - rectW - 0.15;
      if (y + rectH > vb.y + vb.height) y = vb.y + vb.height - rectH - 0.15;

      tip.setAttribute('transform', 'translate(' + x + ',' + y + ')');
    }

    // Displays only the site name while the pointer is over a marker.
    function positionHoverTooltip(evt, el) {
      if (!hoverReady) return;

      var pt;
      if (evt && typeof evt.clientX === 'number' && typeof evt.clientY === 'number') {
        pt = getSvgPoint(evt);
      } else {
        pt = {
          x: parseFloat(el.getAttribute('cx') || el.getAttribute('x') || '0'),
          y: parseFloat(el.getAttribute('cy') || el.getAttribute('y') || '0')
        };
      }

      var rectW = parseFloat(hoverTooltipRect.getAttribute('width')) || 10.70;
      var rectH = parseFloat(hoverTooltipRect.getAttribute('height')) || 2.08;
      var vb = getViewBoxSize();
      var offset = 0.595;
      var x = pt.x + offset;
      var y = pt.y - rectH - offset;

      if (x + rectW > vb.x + vb.width) x = pt.x - rectW - offset;
      if (y < vb.y) y = pt.y + offset;
      if (x < vb.x) x = vb.x + 0.15;
      if (y < vb.y) y = vb.y + 0.15;
      if (x + rectW > vb.x + vb.width) x = vb.x + vb.width - rectW - 0.15;
      if (y + rectH > vb.y + vb.height) y = vb.y + vb.height - rectH - 0.15;

      hoverTip.setAttribute('transform', 'translate(' + x + ',' + y + ')');
    }

    function showHoverName(el, evt) {
      if (!hoverReady || !el) return;
      var siteName = el.getAttribute('data-site-name') || el.getAttribute('data-asset-id') || el.getAttribute('id') || 'Unknown site';
      hoverSiteNameText.textContent = siteName;

      var popupWidth = Math.max(7.14, Math.min(18.42, 1.49 + siteName.length * 0.52));
      hoverTooltipRect.setAttribute('width', popupWidth);
      hoverTip.setAttribute('visibility', 'visible');
      positionHoverTooltip(evt, el);
    }

    function hideHoverName() {
      if (hoverReady) hoverTip.setAttribute('visibility', 'hidden');
    }

    var selectedIndicator = doc.getElementById('selected-site-indicator');

    function updateSelectedIndicator(el) {
      if (!selectedIndicator) return;

      selectedIndicator.setAttribute('data-id-selected', el.getAttribute('id') || '');
      selectedIndicator.setAttribute('data-telemetry-id-selected', el.getAttribute('data-telemetry-id') || '');
      selectedIndicator.setAttribute('data-site-id-selected', el.getAttribute('data-site-id') || '');
      selectedIndicator.setAttribute('data-status-selected', el.getAttribute('data-status') || '');
      selectedIndicator.setAttribute('data-asset-id-selected', el.getAttribute('data-asset-id') || '');
      selectedIndicator.setAttribute('data-site-name-selected', el.getAttribute('data-site-name') || '');

      var cx = el.getAttribute('cx');
      var cy = el.getAttribute('cy');
      if (cx !== null) selectedIndicator.setAttribute('cx', cx);
      if (cy !== null) selectedIndicator.setAttribute('cy', cy);

      var r = parseFloat(el.getAttribute('r')) || 0.3;
      selectedIndicator.setAttribute('r', Math.min(r + 0.12, 0.48));
      selectedIndicator.setAttribute('visibility', 'visible');
    }

    function showSitePopup(el, evt) {
      evt.stopPropagation();
      evt.preventDefault();

      var siteName = el.getAttribute('data-site-name') || el.getAttribute('id') || 'Unknown site';
      var telemetryId = el.getAttribute('data-telemetry-id') || 'N/A';
      var assetId = el.getAttribute('data-asset-id') || 'N/A';

      siteNameText.textContent = siteName;
      telemetryText.textContent = 'Telemetry ID: ' + telemetryId;
      assetText.textContent = 'Asset ID: ' + assetId;

      setTooltipSize(siteName, telemetryId, assetId);
      tip.setAttribute('visibility', 'visible');
      positionTooltip(evt);
      updateSelectedIndicator(el);

      console.log('[SVG Site Popup] clicked:', {
        site_name: siteName,
        telemetry_id: telemetryId,
        asset_id: assetId,
        id: el.getAttribute('id') || '',
        site_id: el.getAttribute('data-site-id') || '',
        status: el.getAttribute('data-status') || '',
        asset_id: el.getAttribute('data-asset-id') || ''
      });
    }

    function hideTooltip(evt) {
      if (evt && evt.target && evt.target.closest && evt.target.closest('.site-marker, .Site, [id^="site-"]')) {
        return;
      }
      hideHoverName();
      tip.setAttribute('visibility', 'hidden');
      if (selectedIndicator) selectedIndicator.setAttribute('visibility', 'hidden');
    }

    sites.forEach(function (site) {
      site.style.cursor = 'pointer';
      site.style.pointerEvents = 'all';
      site.setAttribute('tabindex', '0');

      site.addEventListener('click', function (evt) {
        showSitePopup(this, evt);
      });

      site.addEventListener('keydown', function (evt) {
        if (evt.key === 'Enter' || evt.key === ' ') {
          showSitePopup(this, evt);
        }
      });

      // Hover remains read-only: it only shows the site name and does not
      // stop or alter existing pointer/click/filter interactions.
      site.addEventListener('pointerenter', function (evt) {
        showHoverName(this, evt);
      });
      site.addEventListener('pointermove', function (evt) {
        showHoverName(this, evt);
      });
      site.addEventListener('pointerleave', hideHoverName);
    });

    var resetClickArea = doc.getElementById('map-reset-click-area');
    if (resetClickArea) {
      resetClickArea.addEventListener('click', hideTooltip);
    }

    if (statusLegend) {
      statusLegend.addEventListener('pointerenter', hideHoverName, true);
      statusLegend.addEventListener('pointermove', hideHoverName, true);
      ['pointerdown', 'pointerup', 'mousedown', 'mouseup', 'click', 'dblclick', 'contextmenu'].forEach(function (eventName) {
        statusLegend.addEventListener(eventName, function (evt) {
          hideHoverName();
          evt.preventDefault();
          evt.stopImmediatePropagation();
        }, true);
      });
    }

    svg.addEventListener('pointerleave', hideHoverName);
    svg.addEventListener('click', hideTooltip);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
